import json,sys
m=json.load(open(sys.argv[1])); t=sys.argv[2]
# reconstruct sequence of (cmd, result) pairs
pairs=[]
pending=None
for msg in m:
    tc=msg.get('tool_calls')
    if tc:
        for x in tc:
            fn=x.get('function',{})
            if fn.get('name')=='Bash':
                try: pending=json.loads(fn.get('arguments','{}')).get('command','')
                except: pending=fn.get('arguments','')
    elif msg.get('role')=='tool':
        c=msg.get('content')
        if isinstance(c,list): c=' '.join(str(z.get('text','')) for z in c if isinstance(z,dict))
        pairs.append((pending,c))
# find longest run of identical cmd, check if outputs also identical
best=(0,None,None)
i=0
while i<len(pairs):
    j=i
    while j+1<len(pairs) and pairs[j+1][0]==pairs[i][0]: j+=1
    run=j-i+1
    if run>best[0]:
        outs=[pairs[k][1] for k in range(i,j+1)]
        ident=len(set(outs))==1
        best=(run,pairs[i][0],ident)
    i=j+1
print(f"{t}: run={best[0]} outputs_identical={best[2]} cmd={str(best[1])[:60]!r}")
EOF
